zpl:
{#- ================= ASCEND TAG (designed 2.0" x 1" @ 203 dpi baseline) =================
   `s`  rescales vertical/font quantities by printer.dpi (label height stays fixed at 1").
   `hs` rescales horizontal quantities (x-positions, block widths, barcode max width) by
   the ACTUAL printed width vs. the 2.3" baseline this design was tuned at — so the layout
   compresses correctly whenever label.width is set to something other than 2.3" (e.g. 2.0"),
   not just when dpi changes.
   ^FT (not ^FO) anchors the shop name / code / price fields, matching the original .prn
   export — keep ^FT for those three specifically.
   ^FH\ remaps ZPL's hex-escape indicator from the default '_' to '\', so a literal
   underscore in the shop name/description/code isn't misread as a hex escape.

   ======================================================================================= -#}
{%- set shop_name = "Barrie's Ski and Sports" -%}

{%- set dpi = printer.dpi -%}
{%- set W = (label.width  * dpi) | int -%}
{%- set H = (label.height * dpi) | int -%}
{%- set s  = dpi / 203.0 -%}
{%- set hs = W / (2.3 * 203) -%}

{#- sanitize: ^ and ~ are ZPL control prefixes -#}
{%- set desc  = (doc.description or '') | replace('^',' ') | replace('~',' ') -%}
{#- barcode value: UPC, falling back to Store SKU (Store UPC) when UPC is blank -#}
{%- set code  = (doc.upc or doc.store_sku or '') | string | replace('^',' ') | replace('~',' ') -%}
{%- set price = '$' ~ ('%.2f' | format(doc.price | float)) -%}

{#- barcode geometry: Code 128, module width shrinks (down to 1) so the symbol fits
    max_width, then the bars are centered across W. No barcode is emitted without a
    UPC/Store SKU to encode. -#}
{%- set barcode_y = (94 * s) | int -%}
{%- set barcode_height = (46 * s) | int -%}
{%- set barcode_max_width = (420 * hs) | int -%}
{%- set barcode_zpl = '' -%}
{%- if code -%}
  {%- set modules = 11 * (code | length) + 35 -%}
  {%- set raw_module = barcode_max_width // modules -%}
  {%- set module = [1, [3, raw_module] | min] | max -%}
  {%- set bar_width = modules * module -%}
  {%- set barcode_x = [0, (W - bar_width) // 2] | max -%}
  {%- set barcode_zpl = '^BY' ~ module ~ ',2,' ~ barcode_height ~ '^FO' ~ barcode_x ~ ',' ~ barcode_y
       ~ '^BCN,' ~ barcode_height ~ ',N,N,N^FD' ~ code ~ '^FS' -%}
{%- endif -%}

^XA
^PW{{ W }}
^LL{{ H }}
^LS0
^LH0,0
^CI28
~SD15
^FT{{ (20*hs)|int }},{{ (36*s)|int }}^A0N,{{ (23*s)|int }},{{ (23*s)|int }}^FH\^FD{{ shop_name }}^FS
^FO{{ (16*hs)|int }},{{ (40*s)|int }}^A0N,{{ (24*s)|int }},{{ (24*s)|int }}^FB{{ (416*hs)|int }},2,2,L^FH\^FD{{ desc }}^FS
{{ barcode_zpl }}
^FT{{ (18*hs)|int }},{{ (191*s)|int }}^A0N,{{ (26*s)|int }},{{ (26*s)|int }}^FB{{ (224*hs)|int }},1,0,L^FH\^FD{{ code }}^FS
^FT{{ (248*hs)|int }},{{ (191*s)|int }}^A0N,{{ (37*s)|int }},{{ (38*s)|int }}^FB{{ (170*hs)|int }},1,0,R^FH\^FD{{ price }}^FS
^XZ

{%- set dots = (label.width * printer.dpi) | int -%}
{%- set location = doc.name | replace('^', ' ') | replace('~', ' ') -%}
{%- set module_width = 2 -%}
{%- set barcode_width = (11 * (location | length) + 35) * module_width -%}
{%- set barcode_x = [(dots - barcode_width) // 2, 0] | max -%}
^XA
^PW{{ dots }}
^FO0,20^FB{{ dots }},1,0,C^A0N,30,30^FDBarrie's Warehouse^FS
^FO0,60^FB{{ dots }},1,0,C^A0N,40,40^FDLocation: {{ location }}^FS
^FO{{ barcode_x }},110^BY{{ module_width }}^BCN,80,N,N,N^FD{{ location }}^FS
^XZ

{#- ================= SWAP TAG — rotated 90° clockwise =================
    Design is authored in the original portrait frame (width W, height H,
    stacked top→bottom via ns.y). rtext/rrect map each primitive 90° CW into
    the printed frame, where print width = H and label length = W.
      portrait (x, y) -> printed (H - y, x);  text uses ^A0R.
    TUNING: rotated ^FB/^GB/^BC anchoring varies by firmware. If text prints
    clipped or mirrored, the two things to flip are (a) the rtext origin Y
    between {{ '{{ W }}' }} and 0, and (b) orientation R <-> B.
   ==================================================================== -#}
{%- set dpi = printer.dpi -%}
{%- set W = (label.width  * dpi) | int -%}   {#- design width  (printed length) -#}
{%- set H = (label.height * dpi) | int -%}   {#- design height (printed width)  -#}
{%- set s = dpi / 203.0 -%}                  {#- scale factor, 203 dpi baseline -#}

{#- --- rotation macros: take PORTRAIT coords, emit rotated ZPL --- -#}
{%- macro rtext(y, fh, body) -%}
^FO{{ H - y - fh }},0^FB{{ W }},1,0,C^A0R,{{ fh }},{{ fh }}^FD{{ body }}^FS
{%- endmacro -%}
{%- macro rrect(x, y, w, h, t) -%}
^FO{{ H - y - h }},{{ x }}^GB{{ h }},{{ w }},{{ t }}^FS
{%- endmacro -%}

{#- --- values (sanitize ^/~; None-guarded; standard fieldnames) --- -#}
{%- set brand = (doc.brand or '')      | replace('^',' ') | replace('~',' ') -%}
{%- set model = (doc.style_name or '') | replace('^',' ') | replace('~',' ') -%}
{%- set size  = (doc.size or '')       | replace('^',' ') | replace('~',' ') -%}
{#- barcode: UPC, falling back to Store SKU (Store UPC) when UPC is blank -#}
{%- set barcode = (doc.upc or doc.store_sku or '') | replace('^',' ') | replace('~',' ') -%}
{#- price is Currency (numeric) -> format as money; MSRP maps to price per config -#}
{%- set price_disp = '$' ~ ('%.2f' | format(doc.price | float)) -%}
{%- set msrp_disp  = price_disp -%}

{#- font heights (baseline @203 dpi, scaled by s) -#}
{%- set f_hdr = (26*s)|int -%}{%- set f_brand=(54*s)|int -%}{%- set f_model=(40*s)|int -%}
{%- set f_size=(50*s)|int -%}{%- set f_price=(92*s)|int -%}{%- set f_msrp=(32*s)|int -%}
{%- set f_bar=(52*s)|int -%}{%- set f_pline=(38*s)|int -%}{%- set f_warn=(26*s)|int -%}
{%- set f_num=(24*s)|int -%}

{#- barcode geometry (Code 128) -#}
{%- set module = (2*s) | round(0,'ceil') | int -%}
{%- set bc_h   = (118*s)|int -%}
{%- set bc_w   = (11 * (barcode | length) + 35) * module -%}
{%- set bc_x   = [(W - bc_w) // 2, 0] | max -%}

{%- set ns = namespace(y = (16*s)|int) -%}
^XA
^CI28
^PW{{ H }}
^LL{{ W }}
^LH0,0

{#- BRAND -#}
{{ rtext(ns.y, f_hdr, 'BRAND:') }}{%- set ns.y = ns.y + ((30*s)|int) -%}
{{ rtext(ns.y, f_brand, brand) }}{%- set ns.y = ns.y + ((62*s)|int) -%}

{#- MODEL -#}
{{ rtext(ns.y, f_hdr, 'MODEL:') }}{%- set ns.y = ns.y + ((30*s)|int) -%}
{{ rtext(ns.y, f_model, model) }}{%- set ns.y = ns.y + ((48*s)|int) -%}

{#- SIZE -#}
{{ rtext(ns.y, f_hdr, 'SIZE:') }}{%- set ns.y = ns.y + ((30*s)|int) -%}
{{ rtext(ns.y, f_size, size) }}{%- set ns.y = ns.y + ((58*s)|int) -%}

{#- PRICE -#}
{{ rtext(ns.y, f_hdr, 'PRICE:') }}{%- set ns.y = ns.y + ((32*s)|int) -%}
{{ rtext(ns.y, f_price, price_disp) }}{%- set ns.y = ns.y + ((100*s)|int) -%}

{#- MSRP (struck through) -#}
{%- set msrp_txt = 'MSRP: ' ~ msrp_disp -%}
{{ rtext(ns.y, f_msrp, msrp_txt) }}
{%- set strike_w = (0.55 * f_msrp * (msrp_txt | length)) | int -%}
{%- set strike_x = [(W - strike_w) // 2, 0] | max -%}
{%- set strike_t = (4*s) | round(0,'ceil') | int -%}
{{ rrect(strike_x, ns.y + (f_msrp // 2), strike_w, strike_t, strike_t) }}
{%- set ns.y = ns.y + ((44*s)|int) -%}

{#- dotted separator -#}
{%- set dash=(14*s)|int -%}{%- set dgap=(10*s)|int -%}
{%- set dthk=(4*s)|round(0,'ceil')|int -%}{%- set dm=(18*s)|int -%}
{%- for x in range(dm, W - dm, dash + dgap) -%}{{ rrect(x, ns.y, dash, dthk, dthk) }}{%- endfor -%}
{%- set ns.y = ns.y + ((26*s)|int) -%}

{#- BAR -#}
{{ rtext(ns.y, f_bar, 'BAR') }}{%- set ns.y = ns.y + ((58*s)|int) -%}
{{ rtext(ns.y, f_pline, 'Price: ' ~ price_disp) }}{%- set ns.y = ns.y + ((46*s)|int) -%}
{{ rtext(ns.y, f_warn, 'DO NOT MARK ON BARCODE!') }}{%- set ns.y = ns.y + ((32*s)|int) -%}

{#- human-readable digits above the barcode -#}
{{ rtext(ns.y, f_num, barcode) }}{%- set ns.y = ns.y + ((30*s)|int) -%}

{#- barcode: Code 128, rotated (R). For a true 12-digit UPC-A use ^BUR instead of ^BCR. -#}
^BY{{ module }}
^FO{{ H - ns.y - bc_h }},{{ bc_x }}^BCR,{{ bc_h }},N,N,N^FD{{ barcode }}^FS
^XZ
